      map(function setIsNewForInsertedDoc(doc) {
        if (lean) {
          return doc;
        }
        doc.$__reset();
        _setIsNew(doc, false);
        return doc;
      });

    if (rawResult && ordered === false) {
      decorateBulkWriteResult(error, validationErrors, results);
    }

